// Generated by npm run build:strategies. Edit individual strategy classes.
import Strategy0 from './bitrix.js';
import Strategy1 from './gosuslugi.js';
import Strategy2 from './openai.js';
export const strategyClasses = Object.freeze([Strategy0,Strategy1,Strategy2]);
const byId = new Map(strategyClasses.map(Strategy => [Strategy.id,Strategy]));
export function getStrategy(id) { return byId.get(id) ?? null; }
export const strategyOptions = Object.freeze(strategyClasses.map(({id,domain,displayName,customDomain}) => Object.freeze({id,domain,displayName,customDomain})));
export function strategyScripts(id) { return byId.has(id) ? ['generated/'+id+'.js'] : []; }
export function strategyRoute(id,url,otp=false) { const Strategy = getStrategy(id); if (!Strategy) return false; try { return Strategy.route(url,otp) === true; } catch { return false; } }
